// 13 SPP (dont le capitaine) et 37 SPV : effectif total de 50.
export function volunteerPool(s){s.volunteerPool??=Array.from({length:37},(_,i)=>({id:14+i,tier:i<10?1:i<22?2:3,travel:4+i%8,worker:i%10<7,canLeaveWork:i%4===0,eveningBusy:i%7===0}));s.recallRequests??=[];return s.volunteerPool;}
export function volunteerActivity(p,minute){const h=minute/60%24;return p.worker&&h>=8&&h<18?'work':h>=10&&h<20&&p.id%5===0?'city':'home';}
export function availability(p,minute){const h=minute/60%24;if(p.worker&&!p.canLeaveWork&&h>=8&&h<18)return 'Au travail';if(p.eveningBusy&&h>=18&&h<21)return 'Obligation personnelle';return null;}
function present(s,p){return s.roster.some(r=>r.id===p.id&&r.present);}
function pending(s,p){return s.recallRequests.some(r=>r.personId===p.id&&r.status==='enroute')||s.volunteerReturning?.includes(p.id);}
export function recallCapacity(s){return volunteerPool(s).filter(p=>!present(s,p)&&!pending(s,p)&&!availability(p,s.minute)).length;}
export function requestVolunteers(s,level,rnd=Math.random){if(s.ended||![1,2,3].includes(Number(level)))return 0;level=Number(level);const pool=volunteerPool(s),candidates=pool.filter(p=>(level===3||p.tier===level)&&!present(s,p)&&!pending(s,p));if(!candidates.length)return 0;const batch={id:(s.recallSerial=(s.recallSerial||0)+1),level,at:s.minute,called:candidates.length,unavailable:0};s.recallBatches??=[];s.recallBatches.push(batch);let n=0;for(const p of candidates){if(availability(p,s.minute)){batch.unavailable++;continue;}const night=s.minute/60%24<7||s.minute/60%24>=22;const preparation=(night?3:1)+rnd()*2;s.recallRequests.push({id:p.id+'-'+batch.id,personId:p.id,batch:batch.id,requestedAt:s.minute,activity:volunteerActivity(p,s.minute),preparation,at:s.minute+p.travel+preparation,status:'enroute',phase:'preparing'});n++;}return n;}
export function tickVolunteers(s,emit,arrivalReady=r=>s.minute>=r.at){for(const r of s.recallRequests||[]){if(r.status!=='enroute'||!arrivalReady(r))continue;let p=s.roster.find(p=>p.id===r.personId);const slot=Array.from({length:50},(_,i)=>i).find(i=>!s.roster.some(p=>p.present&&p.slot===i));if(slot==null)continue;if(!p){p={id:r.personId,kind:'SPV',engine:null};s.roster.push(p);}Object.assign(p,{present:true,slot});r.status='arrived';r.phase='available';s.freeStaff=s.roster.filter(p=>p.present&&!p.engine&&!['captain','nurse'].includes(p.role)).length;s.spv=true;emit(`SPV arrivé au CIS · rappel ${r.batch}.`);}}
export function cancelVolunteer(s,id){for(const r of s.recallRequests||[])if(r.batch===Number(id)&&r.status==='enroute')r.status='cancelled';}
const levelName=l=>l===3?'Appel général':'Niveau '+l;
export function volunteerPanel(s){volunteerPool(s);return `<h2>Renforts SPV · 50 personnels</h2><p>13 SPP, dont vous et un infirmier · 37 SPV. Les SPV rejoignent le CIS en voiture personnelle, se garent puis passent aux vestiaires. Ils deviennent disponibles à leur arrivée effective.</p><div class="commandActions">${[1,2,3].map(level=>`<button data-recall-level="${level}" ${s.ended?'disabled':''}>${levelName(level)}</button>`).join('')}</div><p>Niveau 1 : 10 SPV de proximité · Niveau 2 : 12 autres SPV · Général : tous les SPV encore mobilisables, y compris les 15 du dernier groupe.</p><div id="recallStatus">${volunteerStatus(s)}</div><small>Horaires et délais simulés : travail 8 h–18 h, départ du travail possible pour certains SPV, obligations personnelles et préparation plus longue la nuit.</small><button data-close>Fermer</button>`;}
export function volunteerStatus(s){const pool=volunteerPool(s),people=s.roster.filter(p=>p.present&&p.kind==='SPV');return `<p>${people.filter(p=>!p.engine).length} SPV disponibles au CIS · ${people.filter(p=>p.engine).length} engagés · ${recallCapacity(s)} encore joignables et disponibles</p><p>${[1,2,3].map(l=>`${levelName(l)} : ${pool.filter(p=>(l===3||p.tier===l)&&!present(s,p)&&!pending(s,p)&&!availability(p,s.minute)).length} mobilisables`).join(' · ')}</p>${(s.recallBatches||[]).slice(-5).reverse().map(b=>{const requests=s.recallRequests.filter(r=>r.batch===b.id),waiting=requests.filter(r=>r.status==='enroute'),eta=waiting.map(r=>Math.max(0,Math.ceil(r.at-s.minute)));return `<div class="recallBatch"><b>${levelName(b.level)} · appel n°${b.id}</b><p>${b.called} appelés · ${requests.length} réponses positives · ${b.unavailable} indisponibles</p><p>${waiting.length} en approche · ${requests.filter(r=>r.status==='arrived').length} disponibles au CIS · ${requests.filter(r=>r.status==='cancelled').length} annulés</p>${waiting.length?`<p class="recallTravel"><span>${waiting.filter(r=>r.phase==='preparing').length} se préparent</span><span>${waiting.filter(r=>['driving','parking'].includes(r.phase)).length} en voiture</span><span>${waiting.filter(r=>['walking','changing'].includes(r.phase)).length} parking / vestiaires</span></p><p>${waiting.filter(r=>r.activity==='work').length} depuis le travail · ${waiting.filter(r=>r.activity==='home').length} depuis le domicile · ${waiting.filter(r=>r.activity==='city').length} depuis la ville</p><p>Arrivées estimées : ${Math.max(1,Math.round(Math.min(...eta)*60/s.speed))}–${Math.max(1,Math.round(Math.max(...eta)*60/s.speed))} s à cette vitesse · circulation comprise</p>`:''}${waiting.length?`<button data-cancel-recall="${b.id}">Annuler les arrivées restantes</button>`:''}</div>`;}).join('')||'<p>Aucun rappel lancé.</p>'}`;}
export function initObjectives(c,minute,travelMinutes=20){c.objectiveStart=minute;c.arrivalBudget=Math.ceil((12+travelMinutes*1.5)/5)*5;c.finishBudget=c.arrivalBudget+Math.ceil(c.duration*1.5)+20;}
export function objectiveResult(c){return {arrival:c.firstUsefulArrival!=null?c.firstUsefulArrival-c.objectiveStart<=c.arrivalBudget:null,finish:(c.siteCompletedAt??c.closedAt)!=null?(c.siteCompletedAt??c.closedAt)-c.objectiveStart<=c.finishBudget:null};}
export function objectivesPanel(c,minute,speed=60){const result=objectiveResult(c),chip=(label,budget,done,ok)=>{const remaining=Math.ceil(c.objectiveStart+budget-minute),seconds=Math.max(0,Math.round(remaining*60/speed)),real=seconds>=60?Math.floor(seconds/60)+' min '+seconds%60+' s':seconds+' s';return `<span class="objectiveChip ${done!=null?(ok?'objectiveGood':'objectiveLate'):remaining<0?'objectiveLate':''}" title="${label} : objectif ${budget} minutes de garde depuis l’appel. À cette vitesse : ${real} réelles restantes.">${done!=null?(ok?'✓':'⚠'):'◷'} ${label} <b>${done!=null?Math.round(done-c.objectiveStart)+' min':remaining>=0?real+' restantes':'Délai dépassé'}</b></span>`;};return `<section class="objectives compactObjectives" aria-label="Objectifs de mission">${chip('Arrivée',c.arrivalBudget,c.firstUsefulArrival,result.arrival)}${chip('Sur place',c.finishBudget,c.siteCompletedAt??c.closedAt,result.finish)}</section>`;}
